-- Generated localized release notes.
local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"Das Hinweisfenster fasst jetzt jedes kleinere Funktionsupdate und seine Patches auf einer Seite zusammen. Zuerst steht das Funktionsupdate, danach folgen die Patches der Reihe nach mit Version und Datum. Die Verlaufsschaltflächen wechseln zwischen diesen Seiten.","Ältere Patchnotes wurden bereinigt: Sie beschreiben ihre eigenen Änderungen, ohne frühere Anleitungen, Tipps oder Bildschirmfotos zu wiederholen. Reine Patchupdates öffnen das Fenster weiterhin nicht automatisch; /qt notes ist jederzeit verfügbar."},["title"]="Patchnotes"}},["version"]="7.4.3",["welcome"]="Lies jedes Funktionsupdate und seine Patches zusammen."},["esES"]={["sections"]={{["items"]={"La ventana agrupa ahora cada versión menor y sus parches en una página, con la versión menor primero y los parches en orden bajo encabezados con versión y fecha. La navegación del historial pasa entre estas páginas agrupadas.","Se depuraron las notas antiguas para mostrar los cambios de cada parche sin repetir guías, consejos ni capturas anteriores. Las actualizaciones de parche siguen sin abrir la ventana automáticamente; usa /qt notes cuando quieras."},["title"]="Notas de actualización"}},["version"]="7.4.3",["welcome"]="Lee cada actualización y sus parches en una misma página."},["esMX"]={["sections"]={{["items"]={"La ventana ahora agrupa cada versión menor y sus parches en una página, con la versión menor primero y los parches en orden bajo encabezados con versión y fecha. La navegación del historial pasa entre estas páginas agrupadas.","Se depuraron las notas antiguas para mostrar los cambios de cada parche sin repetir guías, consejos ni capturas anteriores. Las actualizaciones de parche siguen sin abrir la ventana automáticamente; usa /qt notes cuando quieras."},["title"]="Notas de actualización"}},["version"]="7.4.3",["welcome"]="Lee cada actualización y sus parches en una misma página."},["frFR"]={["sections"]={{["items"]={"La fenêtre regroupe désormais chaque version mineure et ses correctifs sur une page. La version mineure apparaît en premier, suivie des correctifs dans l’ordre, avec leur version et leur date. La navigation dans l’historique passe d’un groupe à l’autre.","Les anciennes notes de correctifs décrivent maintenant leurs propres changements sans répéter les guides, astuces ou captures précédents. Les correctifs seuls n’ouvrent toujours pas la fenêtre automatiquement ; utilisez /qt notes à tout moment."},["title"]="Notes de mise à jour"}},["version"]="7.4.3",["welcome"]="Lisez chaque mise à jour et ses correctifs sur une même page."},["itIT"]={["sections"]={{["items"]={"La finestra ora raggruppa ogni versione minore e le sue patch in una pagina: prima la versione minore, poi le patch in ordine, con intestazioni che indicano versione e data. La navigazione della cronologia passa tra queste pagine raggruppate.","Le note delle vecchie patch ora descrivono le proprie modifiche senza ripetere guide, consigli o schermate precedenti. Gli aggiornamenti contenenti solo patch continuano a non aprire automaticamente la finestra; usa /qt notes quando vuoi."},["title"]="Note di aggiornamento"}},["version"]="7.4.3",["welcome"]="Leggi ogni aggiornamento e le sue patch nella stessa pagina."},["koKR"]={["sections"]={{["items"]={"이제 각 마이너 버전과 후속 패치를 한 페이지에 모아 표시합니다. 마이너 버전 안내가 먼저 나오고, 버전과 날짜가 표시된 패치가 순서대로 이어집니다. 기록 탐색은 이렇게 묶인 페이지 사이를 이동합니다.","이전 패치 노트에서 기존 기능 안내, 팁, 스크린샷의 반복을 없애고 해당 패치의 변경 사항만 남겼습니다. 패치만 업데이트할 때는 여전히 창이 자동으로 열리지 않으며, 언제든 /qt notes로 열 수 있습니다."},["title"]="패치 노트"}},["version"]="7.4.3",["welcome"]="각 기능 업데이트와 후속 패치를 한 페이지에서 읽으세요."},["ptBR"]={["sections"]={{["items"]={"A janela agora agrupa cada versão secundária e seus patches em uma página, começando pela versão secundária e acrescentando os patches em ordem, com títulos indicando versão e data. A navegação do histórico alterna entre essas páginas agrupadas.","As notas antigas agora mostram as mudanças de cada patch sem repetir guias, dicas ou capturas anteriores. Atualizações apenas de patch continuam sem abrir a janela automaticamente; use /qt notes quando quiser."},["title"]="Notas da atualização"}},["version"]="7.4.3",["welcome"]="Leia cada atualização e seus patches na mesma página."},["ruRU"]={["sections"]={{["items"]={"Окно теперь объединяет каждую минорную версию и её патчи на одной странице: сначала минорная версия, затем патчи по порядку, с номерами версий и датами. Навигация по истории переключает эти объединённые страницы.","Старые заметки к патчам теперь описывают только их изменения, не повторяя предыдущие руководства, советы и снимки экрана. Обновления только с патчами по-прежнему не открывают окно автоматически; используйте /qt notes в любое время."},["title"]="Список изменений"}},["version"]="7.4.3",["welcome"]="Читайте каждое обновление и его исправления на одной странице."},["zhCN"]={["sections"]={{["items"]={"说明窗口现在将每个次版本及其后续补丁合并为一页，先显示次版本说明，再按顺序追加带有版本和日期标题的补丁说明。历史导航会在这些合并后的页面之间切换。","整理了旧补丁说明，只保留各补丁自身的变更，不再重复之前的功能指南、提示或截图。仅更新补丁仍不会自动打开窗口；随时可用 /qt notes 查看。"},["title"]="更新说明"}},["version"]="7.4.3",["welcome"]="在同一页阅读功能更新及其后续补丁。"},["zhTW"]={["sections"]={{["items"]={"說明視窗現在將每個次要版本及其後續修補合併為一頁，先顯示次要版本說明，再依序附上帶有版本和日期標題的修補說明。歷史導覽會在這些合併後的頁面之間切換。","整理了舊修補說明，只保留各修補自身的變更，不再重複先前的功能指南、提示或擷圖。僅更新修補仍不會自動開啟視窗；隨時可用 /qt notes 查看。"},["title"]="更新說明"}},["version"]="7.4.3",["welcome"]="在同一頁閱讀功能更新及其後續修補。"}}
